const crypto = require('crypto');
const headerSig = $input.item.json.headers['x-sahaj-signature'];
const timestamp = $input.item.json.headers['x-sahaj-timestamp'];
const body = $input.item.json.body;

const secret = process.env.HMAC_SECRET || 'sahaj_demo_secret_key_2026';
const data = timestamp + '.' + JSON.stringify(body);
const expectedSig = crypto.createHmac('sha256', secret).update(data).digest('hex');

if (headerSig !== expectedSig) {
  throw new Error('HMAC Signature verification failed');
}

const ticketId = 'HD-2026-' + Math.floor(100000 + Math.random() * 900000);
return [{ json: { ticketId, journeyId: body.journey_id, reason: body.reason, redactedSummary: body.redacted_summary } }];
